  // ---------- Floating manual dice roller ----------
  // DnD-Beyond-style dice tray: click the gold "Rolled" d10 to add one to the rolled pool,
  // click the red "Kept" d10 to add one to the kept pool, "− remove one" takes one back.
  // The formula readout updates live; hitting Roll hands the final X/Y off to the existing
  // rollNotation() -> rollDicePool() -> showRollResult() pipeline — so it still gets the Ten
  // Dice Rule conversion, click-to-keep dice, and exploding 10s for free, same as every other
  // roll button on the sheet.
  let manualRolledCount = 0;
  let manualKeptCount = 0;
  function updateDicePickerDisplay(){
    document.getElementById('rolledBadge').textContent = manualRolledCount;
    document.getElementById('keptBadge').textContent = manualKeptCount;
    document.getElementById('dicePickerFormula').textContent = `${manualRolledCount}k${manualKeptCount}`;
  }
  document.getElementById('floatingDiceBtn').addEventListener('click', ()=>{
    manualRolledCount = 0;
    manualKeptCount = 0;
    updateDicePickerDisplay();
    otherDiceCounts = { d100:0, d20:0, d12:0, d10:0, d8:0, d6:0, d4:0, coin:0 };
    renderOtherDiceRow();
    document.getElementById('otherDiceResult').style.display = 'none';
    document.getElementById('manualRollPromptOverlay').style.display = 'flex';
  });
  document.getElementById('dicePickRolled').addEventListener('click', ()=>{
    manualRolledCount++; updateDicePickerDisplay();
  });
  document.getElementById('dicePickRolledMinus').addEventListener('click', ()=>{
    manualRolledCount = Math.max(0, manualRolledCount-1); updateDicePickerDisplay();
  });
  // Right-click (contextmenu) on the die itself is a shortcut for "− remove one" — prevents
  // the browser's right-click menu so it acts purely as a decrement gesture.
  document.getElementById('dicePickRolled').addEventListener('contextmenu', (e)=>{
    e.preventDefault();
    manualRolledCount = Math.max(0, manualRolledCount-1); updateDicePickerDisplay();
  });
  document.getElementById('dicePickKept').addEventListener('click', ()=>{
    manualKeptCount++; updateDicePickerDisplay();
  });
  document.getElementById('dicePickKeptMinus').addEventListener('click', ()=>{
    manualKeptCount = Math.max(0, manualKeptCount-1); updateDicePickerDisplay();
  });
  document.getElementById('dicePickKept').addEventListener('contextmenu', (e)=>{
    e.preventDefault();
    manualKeptCount = Math.max(0, manualKeptCount-1); updateDicePickerDisplay();
  });
  document.getElementById('dicePickerClear').addEventListener('click', ()=>{
    manualRolledCount = 0; manualKeptCount = 0; updateDicePickerDisplay();
  });
  document.getElementById('manualRollPromptClose').addEventListener('click', ()=>{
    document.getElementById('manualRollPromptOverlay').style.display = 'none';
  });
  document.getElementById('manualRollPromptOverlay').addEventListener('click', (e)=>{
    if(e.target.id==='manualRollPromptOverlay') document.getElementById('manualRollPromptOverlay').style.display = 'none';
  });
  function submitManualRoll(){
    document.getElementById('manualRollPromptOverlay').style.display = 'none';
    rollNotation('Manual Roll', `${manualRolledCount}k${manualKeptCount}`); // rollNotation applies the Ten Dice Rule internally
    // Clear the pool immediately after rolling, not just the next time the picker is opened.
    manualRolledCount = 0;
    manualKeptCount = 0;
    updateDicePickerDisplay();
  }
  document.getElementById('manualRollSubmit').addEventListener('click', submitManualRoll);

  // ---------- Other Dice (d20 / d12 / d10 / d8 / d4 / Coin) ----------
  // Plain flat dice, separate from the L5R d10 roll-and-keep pool above: no Ten Dice Rule,
  // no exploding on a max result — a standalone d10 here is just 1-10, not part of XkY.
  // Same tap-to-add picker pattern as the XkY pool for a consistent feel.
  const OTHER_DIE_TYPES = [
    {key:'d20', sides:20, label:'d20', icon:'data:image/png;base64,'},
    {key:'d12', sides:12, label:'d12', icon:'data:image/png;base64,'},
    {key:'d100',sides:100,label:'d100',icon:'data:image/png;base64,'},
    {key:'d10', sides:10, label:'d10', icon:'data:image/png;base64,'},
    {key:'d8',  sides:8,  label:'d8',  icon:'data:image/png;base64,'},
    {key:'d6',  sides:6,  label:'d6',  icon:'data:image/png;base64,'},
    {key:'d4',  sides:4,  label:'d4',  icon:'data:image/png;base64,'},
    {key:'coin',sides:2,  label:'Coin', icon:'data:image/png;base64,'},
  ];
  let otherDiceCounts = { d100:0, d20:0, d12:0, d10:0, d8:0, d6:0, d4:0, coin:0 };
  function renderOtherDiceRow(){
    const row = document.getElementById('otherDiceRow');
    row.innerHTML = OTHER_DIE_TYPES.map(t=>`
      <div class="other-die-cell">
        <button type="button" class="other-die-btn${t.icon?' has-icon':''}" data-key="${t.key}" title="Click to add a ${t.label}, right-click to remove one">${
          t.icon ? `<img src="${t.icon}" alt="${t.label}" class="other-die-icon"><span class="other-die-icon-label">${t.label}</span>` : t.label
        }</button>
        <span class="other-die-badge" id="otherBadge_${t.key}">${otherDiceCounts[t.key]}</span>
        <button type="button" class="other-die-minus" data-key="${t.key}">− remove</button>
      </div>
    `).join('');
    row.querySelectorAll('.other-die-btn').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        otherDiceCounts[btn.dataset.key]++;
        document.getElementById('otherBadge_'+btn.dataset.key).textContent = otherDiceCounts[btn.dataset.key];
      });
      // Right-click the die itself as a shortcut for "− remove one" (prevents the browser's
      // context menu so the gesture reads purely as a decrement).
      btn.addEventListener('contextmenu', (e)=>{
        e.preventDefault();
        otherDiceCounts[btn.dataset.key] = Math.max(0, otherDiceCounts[btn.dataset.key]-1);
        document.getElementById('otherBadge_'+btn.dataset.key).textContent = otherDiceCounts[btn.dataset.key];
      });
    });
    row.querySelectorAll('.other-die-minus').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        otherDiceCounts[btn.dataset.key] = Math.max(0, otherDiceCounts[btn.dataset.key]-1);
        document.getElementById('otherBadge_'+btn.dataset.key).textContent = otherDiceCounts[btn.dataset.key];
      });
    });
  }
  renderOtherDiceRow();
  document.getElementById('otherDiceClear').addEventListener('click', ()=>{
    otherDiceCounts = { d100:0, d20:0, d12:0, d10:0, d8:0, d6:0, d4:0, coin:0 };
    renderOtherDiceRow();
    document.getElementById('otherDiceResult').style.display = 'none';
  });
  document.getElementById('otherDiceRoll').addEventListener('click', ()=>{
    const numericLines = [];
    let total = 0;
    OTHER_DIE_TYPES.filter(t=>t.key!=='coin').forEach(t=>{
      const n = otherDiceCounts[t.key];
      if(n<=0) return;
      const rolls = [];
      for(let i=0;i<n;i++){ const r = 1+Math.floor(Math.random()*t.sides); rolls.push(r); total += r; }
      numericLines.push(`${n}${t.label}: [${rolls.join(', ')}] = ${rolls.reduce((a,b)=>a+b,0)}`);
    });
    let coinLine = '';
    const coinN = otherDiceCounts.coin;
    if(coinN>0){
      const flips = [];
      for(let i=0;i<coinN;i++) flips.push(Math.random()<0.5 ? 'Heads' : 'Tails');
      coinLine = `Coin ×${coinN}: ${flips.join(', ')}`;
    }
    if(!numericLines.length && !coinLine){
      setStatus('Add at least one die before rolling.');
      return;
    }
    const resultEl = document.getElementById('otherDiceResult');
    resultEl.style.display = 'block';
    resultEl.innerHTML =
      (numericLines.length ? `<div class="roll-total">${total}</div>` : '') +
      numericLines.map(l=>`<div class="other-dice-line">${escHtml(l)}</div>`).join('') +
      (coinLine ? `<div class="other-dice-line">${escHtml(coinLine)}</div>` : '');
    // Clear the queued dice immediately after rolling, not just the next time this is opened.
    otherDiceCounts = { d100:0, d20:0, d12:0, d10:0, d8:0, d6:0, d4:0, coin:0 };
    renderOtherDiceRow();
  });

  // Closing the Roll modal (✕ or clicking outside it) is the one reliable "the player is done
  // adjusting kept dice" moment for a TN roll — see currentRollOnClose above — so this is where
  // any queued onClose callback (currently only castMahoSpell's Taint-gain-on-success step)
  // fires, reading the same success/failure state the pass/fail readout already shows.
  function closeRollModal(){
    const resultNote = document.getElementById('rollResultNote');
    const success = (currentRollTN!==null && resultNote) ? resultNote.classList.contains('success') : null;
    document.getElementById('rollModalOverlay').style.display = 'none';
    if(currentRollOnClose){
      const cb = currentRollOnClose;
      currentRollOnClose = null;
      cb(success);
    }
  }
  document.getElementById('rollModalClose').addEventListener('click', closeRollModal);
  document.getElementById('rollModalOverlay').addEventListener('click', (e)=>{
    if(e.target.id==='rollModalOverlay') closeRollModal();
  });

  // ---------- Skill Info Modal ----------
  // Holds the currently-bound Phase 3 debug-button handlers so showSkillInfoModal() can
  // unbind the previous skill's closures before binding the next skill's — see the comment
  // inside that function where this is read/written.
  const skillInfoDebugCurrentHandlers = { structured:null, freeText:null };
  function showSkillInfoModal(tr){
    const name = tr.querySelector('.sk-name').value.trim() || 'Unnamed Skill';
    const rank = parseInt(tr.querySelector('.sk-rank').value||'0',10);
    const traitName = tr.querySelector('.sk-trait').value.trim();
    const traitVal = getTraitValueByName(traitName);

    let rollStr = '—';
    if(traitName){
      // X = Skill Rank + Trait Rank, Y = Trait Rank.
      const numDice = rank<=0 ? traitVal : traitVal + rank;
      const keepDice = traitVal;
      rollStr = formatRollNotation(numDice, keepDice);
    }

    const lib = findSkill(name);
    document.getElementById('skillInfoTitle').textContent = name;
    document.getElementById('skillInfoCategory').textContent = lib ? `${lib.cat} Skill` : 'Custom Skill';
    document.getElementById('skillInfoStats').innerHTML = `
      <div><span>Current Rank</span><strong>${rank}</strong></div>
      <div><span>Linked Trait</span><strong>${escHtml(traitName||'—')}</strong></div>
      <div><span>Base Roll</span><strong>${rollStr}</strong></div>
      <div><span>School Skill</span><strong>${tr.querySelector('.sk-school').checked?'Yes':'No'}</strong></div>
    `;
    const desc = SKILL_DESCRIPTIONS[name] || 'No official description on file for this skill — likely a custom or homebrew entry.';
    document.getElementById('skillInfoDesc').innerHTML = `<strong>Official Description:</strong> ${escHtml(desc)}`;

    const emphNow = getEmphValues(tr);
    const emphLine = lib && lib.emph && lib.emph!=='—' ? `Possible Emphases: ${escHtml(lib.emph)}` : '';
    const takenLine = emphNow.length ? `Currently taken: ${escHtml(emphNow.join(', '))}` : '';
    document.getElementById('skillInfoEmph').innerHTML = [emphLine, takenLine].filter(Boolean).join('<br>');

    // PHASE 3 debug UI wiring — re-bound every time the modal opens, using the same
    // remove-then-add pattern this file already uses elsewhere for repeat-safe modal buttons
    // (see the Promise-based confirm/pick modals' onConfirm/onCancel removeEventListener calls)
    // so each button always reads the CURRENTLY displayed skill's name/rank, not whichever
    // skill happened to be open when the listener was first attached. Both handlers are
    // read-only: they call the Phase 2 pure helpers (or read lib.m directly) and write the
    // result into skillInfoDebugOutput. Neither calls a roller, neither writes to any hidden
    // input, neither is called by anything else — clicking these buttons cannot change what
    // any roll produces. skillInfoDebugCurrentHandlers persists the last-bound pair across
    // calls (module-scope, declared once near the top of this function's enclosing scope)
    // purely so it can be unbound here before rebinding.
    const debugOutput = document.getElementById('skillInfoDebugOutput');
    debugOutput.style.display = 'none';
    debugOutput.textContent = '';
    const structuredBtn = document.getElementById('skillInfoShowStructured');
    const freeTextBtn = document.getElementById('skillInfoShowFreeText');
    if(skillInfoDebugCurrentHandlers.structured) structuredBtn.removeEventListener('click', skillInfoDebugCurrentHandlers.structured);
    if(skillInfoDebugCurrentHandlers.freeText) freeTextBtn.removeEventListener('click', skillInfoDebugCurrentHandlers.freeText);
    skillInfoDebugCurrentHandlers.structured = ()=>{
      const raw = getStructuredMastery(name);
      const resolved = {
        dmgBonus: getDamageBonus(name, rank),
        explodeOn: getExplosionThreshold(name, rank),
        reductionMod: getReductionModifier(name, rank),
      };
      const lines = [
        `Structured mastery — ${name} (current rank ${rank})`,
        '',
        'Raw thresholds (all ranks, from SKILL_LIBRARY):',
        `  dmgBonus:     ${raw.dmgBonus ? JSON.stringify(raw.dmgBonus) : '(none defined)'}`,
        `  explodeOn:    ${raw.explodeOn ? JSON.stringify(raw.explodeOn) : '(none defined)'}`,
        `  reductionMod: ${raw.reductionMod ? JSON.stringify(raw.reductionMod) : '(none defined)'}`,
        '',
        `Resolved at rank ${rank} (thresholds <= rank applied, cumulative):`,
        `  dmgBonus:     +${resolved.dmgBonus.roll}k${resolved.dmgBonus.keep}`,
        `  explodeOn:    ${resolved.explodeOn===null ? '(no change — default explode-on-10 behaviour)' : resolved.explodeOn}`,
        `  reductionMod: ${resolved.reductionMod}`,
        '',
        'Not applied to any roll — see mastery refactor Phase 4/5.',
      ];
      debugOutput.textContent = lines.join('\n');
      debugOutput.style.display = 'block';
    };
    skillInfoDebugCurrentHandlers.freeText = ()=>{
      const lines = [`Free-text mastery — ${name} (current rank ${rank})`, ''];
      if(!lib || !lib.m || Object.keys(lib.m).length===0){
        lines.push('(no mastery abilities on file for this skill)');
      } else {
        [3,5,7].filter(t=>lib.m[t]).forEach(t=>{
          lines.push(`  R${t}${rank>=t?' ✓':'  '}: ${lib.m[t]}`);
        });
      }
      debugOutput.textContent = lines.join('\n');
      debugOutput.style.display = 'block';
    };
    structuredBtn.addEventListener('click', skillInfoDebugCurrentHandlers.structured);
    freeTextBtn.addEventListener('click', skillInfoDebugCurrentHandlers.freeText);

    document.getElementById('skillInfoModalOverlay').style.display = 'flex';
  }
  document.getElementById('skillInfoClose').addEventListener('click', ()=>{
    document.getElementById('skillInfoModalOverlay').style.display = 'none';
  });
  document.getElementById('skillInfoModalOverlay').addEventListener('click', (e)=>{
    if(e.target.id==='skillInfoModalOverlay') document.getElementById('skillInfoModalOverlay').style.display = 'none';
  });

  // ---------- Untrained Skills ----------
  // "Untrained" = no Rank anywhere: every Skill Library entry the character hasn't put a
  // Rank in (whether or not it's even been added to the table via Quick Add / Load Full
  // Skill List), plus any of the character's own custom-named rows still sitting at Rank 0.
  // Each entry carries its Trait too, so a click in the modal can perform an Unskilled Roll.
  function getUntrainedSkillsGrouped(){
    const trainedNames = new Set();
    const customUntrained = [];
    document.querySelectorAll('#skillsBody tr').forEach(tr=>{
      const nameEl = tr.querySelector('.sk-name');
      const rankEl = tr.querySelector('.sk-rank');
      const traitEl = tr.querySelector('.sk-trait');
      if(!nameEl) return;
      const name = nameEl.value.trim();
      if(!name) return;
      const rank = parseInt(rankEl.value||'0',10);
      if(rank>0){ trainedNames.add(name.toLowerCase()); }
      else if(!findSkill(name)){ customUntrained.push({name, trait: traitEl?traitEl.value.trim():''}); }
    });
    const cats = ['High','Bugei','Weapon','Weapon (Low)','Merchant','Low'];
    const grouped = cats.map(cat=>({
      cat,
      skills: SKILL_LIBRARY.filter(s=>s.cat===cat && !trainedNames.has(s.name.toLowerCase()))
        .map(s=>({name:s.name, trait:s.trait})),
    })).filter(g=>g.skills.length);
    if(customUntrained.length){ grouped.push({ cat:'Custom / Added (Rank 0)', skills:customUntrained }); }
    return grouped;
  }
  function showUntrainedSkillsModal(){
    const groups = getUntrainedSkillsGrouped();
    const total = groups.reduce((n,g)=>n+g.skills.length,0);
    document.getElementById('untrainedSkillsCount').textContent =
      total ? `${total} skill${total===1?'':'s'} with no Rank — click one for an Unskilled Roll` : 'Every skill currently has a Rank!';
    document.getElementById('untrainedSkillsBody').innerHTML = groups.length ? groups.map(g=>`
      <div class="untrained-group">
        <div class="untrained-group-title">${escHtml(g.cat)}</div>
        <div class="untrained-group-list">${g.skills.map(s=>
          `<button type="button" class="untrained-chip" data-skill-name="${escAttr(s.name)}" data-trait-name="${escAttr(s.trait||'')}" title="${s.trait?`Unskilled Roll — ${escAttr(s.trait)} (10s do not explode)`:'No linked Trait on file'}">${escHtml(s.name)}</button>`
        ).join('')}</div>
      </div>
    `).join('') : '<div class="hint">Nothing untrained — every skill in the library has a Rank.</div>';
    document.getElementById('untrainedSkillsModalOverlay').style.display = 'flex';
  }
  document.getElementById('btnUntrainedSkills').addEventListener('click', showUntrainedSkillsModal);
  document.getElementById('untrainedSkillsClose').addEventListener('click', ()=>{
    document.getElementById('untrainedSkillsModalOverlay').style.display = 'none';
  });
  document.getElementById('untrainedSkillsModalOverlay').addEventListener('click', (e)=>{
    if(e.target.id==='untrainedSkillsModalOverlay') document.getElementById('untrainedSkillsModalOverlay').style.display = 'none';
  });
  // Clicking an untrained skill performs an Unskilled Roll: it's rolled exactly like a Trait
  // Roll (rank kept rank, off the skill's linked Trait) and still goes through the shared
  // rollDicePool()/showRollResult() pipeline (so the Ten Dice Rule still applies) — the one
  // difference is 10s do NOT explode on an Unskilled Roll, per the rules.
  document.getElementById('untrainedSkillsBody').addEventListener('click', e=>{
    const chip = e.target.closest('.untrained-chip');
    if(!chip) return;
    const skillName = chip.dataset.skillName;
    const traitName = chip.dataset.traitName;
    if(!traitName){ setStatus(`${skillName} has no linked Trait on file — can't roll it Unskilled.`); return; }
    const rank = getTraitValueByName(traitName);
    document.getElementById('untrainedSkillsModalOverlay').style.display = 'none';
    // PART C FEATURE 3 - routed through P2. `explode:false` is passed straight through,
    // so an Unskilled roll still does not explode on 10.
    // traitName rides along purely so a reader can be shown WHERE the pool came from (Part G
    // Phase 3's preview prints "Agility 3 — Unskilled"). No contributor reads it, so it costs
    // nothing if that phase is ever removed.
    rollWithModifiers(`${skillName} (Unskilled)`,
      makeRollContext(ROLL_KINDS.SKILL, { skillName, traitName, unskilled:true,
        // PART G PHASE 4 - on an Unskilled Roll the rank IS the Trait value, which is exactly
        // what the breakdown needs to say the Trait rolls and keeps alone.
        traitValue:rank }),
      rank, rank, { explode:false });
  });

  document.getElementById('addSkill').addEventListener('click', ()=>{ document.getElementById('skillsBody').appendChild(makeSkillRow()); recalcAll(); });
  document.getElementById('loadAllSkills').addEventListener('click', ()=>{
    const existing = new Set(Array.from(document.querySelectorAll('#skillsBody .sk-name')).map(el=>el.value.trim().toLowerCase()));
    let added = 0;
    SKILL_LIBRARY.forEach(s=>{
      if(existing.has(s.name.toLowerCase())) return;
      document.getElementById('skillsBody').appendChild(makeSkillRow({name:s.name, trait:s.trait, rank:0, emph:''}));
      added++;
    });
    recalcAll();
    setStatus(added? `Added ${added} skills.` : 'All skills already listed.');
  });
  // "+ Add Weapon" makes a blank, unlinked row (key:'' — an explicit custom weapon, not a
  // legacy row), so typing a canonical name into it is what links it to the library.
  document.getElementById('addWeapon').addEventListener('click', ()=>{
    document.getElementById('weaponsBody').appendChild(makeWeaponRow({key:''}));
    refreshAllWeaponRows();   // PART C FEATURE 7 - a second weapon reveals the Hand selector
  });
  buildWeaponQuickAdd();
  // PART C P1 — round tracker controls.
  document.getElementById('btnNextRound').addEventListener('click', ()=>{
    advanceCombatRound(); recalcAll(); renderStanceTiles(); renderVoidPanel();
    setStatus('Round ' + getCombatRound() + '.');
  });
  document.getElementById('btnResetRounds').addEventListener('click', ()=>{
    resetCombatRound(); clearFullDefenseBonus(); setCurrentStance(DEFAULT_STANCE, {silent:true});
    clearVoidPending(); clearVoidSkirmishEffects(); recalcAll(); renderVoidPanel();
    setStatus('Combat rounds reset.');
  });
  renderCombatRoundUI();
  document.getElementById('addEquip').addEventListener('click', ()=>document.getElementById('equipBody').appendChild(makeEquipRow()));
  // Opens the "Spell Scrolls" pop-up — a scrollable, Element-grouped list of every spell in
  // SPELL_LIBRARY, one row per spell — rather than adding an Equipment row directly. The
  // button itself is only ever visible for a Shugenja to begin with — see
  // updateSpellSlotsVisibility() — so there's no need to re-check that here.
  document.getElementById('addSpellScroll').addEventListener('click', ()=>{
    document.getElementById('spellScrollSearch').value = '';
    document.getElementById('spellScrollsNote').textContent = '';
    renderSpellScrollsList('');
    document.getElementById('spellScrollsModalOverlay').style.display = 'flex';
  });
  // Rebuilds the list HTML (grouped by Element, in the same order the Technique/Spell
  // quick-add dropdown uses) filtered by name against the search box, and wires each row's
  // "+ Add" button fresh since the row elements themselves are recreated every render.
  // Maho spells keep their real Ring in `element` (Fire/Earth/Air/Water) — that field still
  // drives casting/eligibility/effectiveSchoolRankForElement everywhere else, unchanged — but
  // are additionally flagged `maho:true` purely so this picker can group them under their own
  // "Maho" heading instead of blending into their Ring's group. The 'Maho' filter below matches
  // on that flag; every other group's filter now also excludes maho:true spells, so a Maho
  // spell appears exactly once (under Maho), never doubled into its Ring's group as well.
  function renderSpellScrollsList(filterText){
    const list = document.getElementById('spellScrollsList');
    const q = (filterText||'').trim().toLowerCase();
    const order = ['Universal','Air','Earth','Fire','Water','Void','Maho'];
    let html = '';
    order.forEach(el=>{
      const items = SPELL_LIBRARY
        .map((s,i)=>({...s,i}))
        .filter(s=> (el==='Maho' ? s.maho===true : (s.element===el && !s.maho)) && (!q || s.name.toLowerCase().includes(q)));
      if(!items.length) return;
      html += `<div class="spell-scrolls-group-label">${escHtml(el)}</div>`;
      items.forEach(s=>{
        html += `
        <div class="spell-scroll-row">
          <div><span class="ssr-name">${escHtml(s.name)}</span><span class="ssr-meta">${escHtml(s.element)} ${s.mastery}</span></div>
          <button type="button" class="ghost spell-scroll-add-btn" data-idx="${s.i}">+ Add</button>
        </div>`;
      });
    });
    list.innerHTML = html || '<div class="roll-note" style="padding:10px;">No spells match.</div>';
    list.querySelectorAll('.spell-scroll-add-btn').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        const s = SPELL_LIBRARY[parseInt(btn.dataset.idx,10)];
        const label = `Spell Scroll — ${s.name}`;
        const notes = `A scroll with the prayer for ${s.name}, reciting the prayer allows the reader to cast the spell.`;
        document.getElementById('equipBody').appendChild(makeEquipRow({name:label, qty:1, notes}));
        document.getElementById('spellScrollsNote').textContent = `Added "${label}" to Equipment.`;
        // Unlocks this spell in the Technique/Spell quick-add dropdown immediately (see
        // hasSpellScroll/techQuickAddOptionsHTML) — no pop-up, per spec: acquiring the scroll
        // just quietly removes the padlock the next time the dropdown is (re)built.
        recalcAll();
      });
    });
  }
  document.getElementById('spellScrollSearch').addEventListener('input', ()=>{
    renderSpellScrollsList(document.getElementById('spellScrollSearch').value);
  });
  document.getElementById('spellScrollsX').addEventListener('click', ()=>{
    document.getElementById('spellScrollsModalOverlay').style.display = 'none';
  });
  document.getElementById('addAdv').addEventListener('click', ()=>{ document.getElementById('advList').appendChild(makeEntry({},true)); recalcAll(); });
  document.getElementById('addDisadv').addEventListener('click', ()=>{ document.getElementById('disadvList').appendChild(makeEntry({},true)); recalcAll(); });
  document.getElementById('addTech').addEventListener('click', ()=>document.getElementById('techList').appendChild(makeEntry({},true,'XP')));

  // Delegated input listeners so dynamically-added rows feed the calculator
  document.getElementById('skillsBody').addEventListener('input', recalcAll);
  document.getElementById('skillsBody').addEventListener('change', recalcAll);
  document.getElementById('advList').addEventListener('input', recalcAll);
  document.getElementById('disadvList').addEventListener('input', recalcAll);
  document.getElementById('techList').addEventListener('input', recalcAll);
  // Live-updates spell-scroll gating (see hasSpellScroll/techQuickAddOptionsHTML) as the
  // player types directly into an Equipment row's Item name — e.g. renaming a row into or out
  // of "Spell Scroll — X" — without needing to blur the field or take any other action first.
  document.getElementById('equipBody').addEventListener('input', recalcAll);

  // ---------- Wounds (PART H PHASE 1.6: horizontal severity bar) ----------
  // computeWoundThresholds(), WOUND_LEVELS and showWoundInfoModal()'s CALLERS changed here;
  // the classification math itself did not. getCurrentWoundLevelName()/getWoundPenalty() in
  // 170-feat-wounds.js read the same two pieces and are untouched by this phase.
  function computeWoundThresholds(earth){
    let cum = earth*2;
    const thresholds = [];
    WOUND_LEVELS.forEach((lvl,i)=>{
      if(i===0){ thresholds.push(cum); }
      else { cum += earth; thresholds.push(cum); }
    });
    return thresholds;
  }
  // Same wording the old per-row layout used, extracted rather than duplicated so the
  // summary line, each segment's aria-label, and the info modal can never disagree with
  // each other about what a level's penalty says.
  function formatWoundPenalty(lvl){
    if(lvl.pen === '—') return 'No TN penalty';
    if(lvl.pen === 'Unconscious') return 'Unconscious';
    return `TN of all rolls +${lvl.pen.replace('-','')}`;
  }
  // One CSS-facing severity band per WOUND_LEVELS entry, in order: Healthy is the sheet's
  // own "success" tone, Nicked/Grazed read as a caution, Hurt through Down as the sheet's
  // danger colour, and Out drops to ink -- unconscious, not merely hurt. Colour is never the
  // only signal (see the aria-label building below), per the validation suite's accessibility row.
  const WOUND_SEVERITY = ['ok','warn','warn','danger','danger','danger','danger','out'];
  function renderWounds(){
    const earth = parseInt(document.getElementById('ring_earth').value||'2',10);
    const takenEl = document.getElementById('f_woundsTaken');
    const taken = parseInt(takenEl.value||'0',10);
    const thresholds = computeWoundThresholds(earth);
    const maxWounds = thresholds[thresholds.length-1];
    let currentIdx = thresholds.findIndex(t=>taken<=t);
    if(currentIdx===-1) currentIdx = WOUND_LEVELS.length-1;
    const lvl = WOUND_LEVELS[currentIdx];

    // ---- summary + next-level lines ----
    const summary = document.getElementById('woundSummaryLine');
    if(summary){
      summary.textContent = `${lvl.name} — ${formatWoundPenalty(lvl)} — ${taken} of ${maxWounds} wound points`;
    }
    const nextLine = document.getElementById('woundNextLine');
    if(nextLine){
      if(currentIdx >= WOUND_LEVELS.length-1){
        nextLine.textContent = 'Already at the last level.';
      } else {
        // Formula per spec: remaining = thresholds[currentIndex] + 1 - woundsTaken. Since
        // currentIdx is the first threshold >= taken, this is always >= 1 -- there is no
        // zero/negative case to special-case here.
        const remaining = thresholds[currentIdx] + 1 - taken;
        const nextLvl = WOUND_LEVELS[currentIdx+1];
        nextLine.textContent = `${remaining} wound${remaining===1?'':'s'} to ${nextLvl.name}`;
      }
    }

    // ---- the 8-segment bar ----
    const bar = document.getElementById('woundBar');
    if(bar){
      bar.innerHTML = '';
      WOUND_LEVELS.forEach((l,i)=>{
        const seg = document.createElement('button');
        seg.type = 'button';
        seg.className = `wound-seg sev-${WOUND_SEVERITY[i]}` + (i===currentIdx ? ' current' : '');
        seg.setAttribute('aria-label', `${l.name} — ${formatWoundPenalty(l)}`);
        seg.title = l.name;
        seg.addEventListener('click', ()=>showWoundInfoModal(l));
        bar.appendChild(seg);
      });
    }

    // ---- the three synced controls: slider, number box, +/- stepper ----
    // f_woundsTaken (the number box) is the one persisted field -- collectData() serialises
    // every [id^="f_"] element, and only one element may hold that id. The slider and stepper
    // are UI-only: every change funnels back through this same input's value, so nothing new
    // is added to the save format.
    const slider = document.getElementById('woundsTakenSlider');
    if(slider){ slider.max = maxWounds; slider.value = taken; }
    const stepDown = document.getElementById('woundStepDown');
    const stepUp = document.getElementById('woundStepUp');
    if(stepDown) stepDown.disabled = (taken <= 0);
    if(stepUp) stepUp.disabled = (taken >= maxWounds);

    // PART H PHASE 2 - renderWounds() is called both by recalcAll() (last thing it does) and
    // directly by the wound stepper/slider, which bypass recalcAll() entirely (see the comment
    // above woundsTakenSlider's own listener). Refreshing the Quick Access panel here, rather
    // than only at the tail of recalcAll(), is what makes the panel's Wounds row -- and by the
    // same reasoning, its Armor TN and Initiative rows, since recalcAll() always finishes with
    // this call -- update in every case the roadmap's "updates instantly when values change"
    // actually needs to cover, not only a full recalc pass.
    if(typeof renderQuickAccessPanel === 'function') renderQuickAccessPanel();
  }
  // Generalized over the old per-row layout, which only ever called this for the row a
  // player happened to click -- but every row already carried its own info button, so every
  // level was already reachable this way. The segmented bar above wires the same call per
  // segment; the function itself needed no change.
  function showWoundInfoModal(lvl){
    document.getElementById('woundInfoTitle').textContent = lvl.name;
    document.getElementById('woundInfoPen').textContent = formatWoundPenalty(lvl);
    document.getElementById('woundInfoDesc').textContent = lvl.desc;
    document.getElementById('woundInfoModalOverlay').style.display = 'flex';
  }
  document.getElementById('woundInfoClose').addEventListener('click', ()=>{
    document.getElementById('woundInfoModalOverlay').style.display = 'none';
  });
  document.getElementById('woundInfoModalOverlay').addEventListener('click', (e)=>{
    if(e.target.id==='woundInfoModalOverlay') document.getElementById('woundInfoModalOverlay').style.display = 'none';
  });

  // ---------- XP costs (L5R 4e core rules) ----------
  // Traits & Void start at rank 2 for free; each step up costs (new rank) x multiplier.
  function stepUpCost(fromRank, toRank, perStepMultiplier){
    let cost = 0;
    for(let step = fromRank+1; step <= toRank; step++){ cost += step * perStepMultiplier; }
    return cost;
  }
  function traitCost(rank, freeFloor){
    const floor = (freeFloor==null || isNaN(freeFloor)) ? 2 : freeFloor;
    return stepUpCost(floor, rank, 4);
  }
  function voidCost(rank, freeFloor){
    const floor = (freeFloor==null || isNaN(freeFloor)) ? 2 : freeFloor;
    return stepUpCost(floor, rank, 6);
  }
  // Skill cost: buying rank 1 costs 1 XP, rank 2 costs 2 more, etc — cumulative = N(N+1)/2.
  // freeFloor works exactly like a Trait's data-free "floor": XP is only owed for the portion
  // of the current Rank above that floor (cumulative(rank) - cumulative(floor)), so a School
  // that grants a skill at Rank 2 (e.g. Kuni Shugenja's Lore: Shadowlands 2) costs 0 XP up to
  // Rank 2, while Rank 3 still costs the normal 3 XP step on top. A manually-ticked "School
  // Skill" checkbox with no explicit floor set defaults to the standard "first Rank free"
  // rule (floor 1) — see the skillXP loop below, which is the only caller and decides freeFloor.
  function skillCumulative(rank){ return rank>0 ? (rank*(rank+1))/2 : 0; }
  function skillCost(rank, emphCount, freeFloor){
    const floor = Math.max(0, Math.min(rank, freeFloor||0));
    let cost = Math.max(0, skillCumulative(rank) - skillCumulative(floor));
    cost += Math.max(0, emphCount)*2;
    return cost;
  }
  function insightRankFromPoints(pts){
    return calculateSchoolRank(pts).rank;
  }

  // ---------- Void Points pip tracker ----------
  // void_current (hidden input, kept for save/load compatibility) holds the count of
  // currently-filled pips. The visible pips are just that many circles filled in, out of
  // a total equal to the current Void Ring rank.
  // Tracks the Void rank as of the last render, so we can tell an *increase* in rank
  // (new pips should start filled) apart from just re-rendering at the same rank.
  let prevVoidRank = null;
  function renderVoidPips(){
    const rank = Math.max(1, Math.min(10, parseInt(document.getElementById('ring_void').value||'1',10)));
    const hidden = document.getElementById('void_current');
    let current = Math.max(0, parseInt(hidden.value||'0',10));
    if(prevVoidRank !== null && rank > prevVoidRank){
      current += (rank - prevVoidRank); // newly added pips start filled
    }
    current = Math.max(0, Math.min(rank, current));
    hidden.value = current;
    prevVoidRank = rank;
    const wrap = document.getElementById('voidPips');
    wrap.innerHTML = '';
    for(let i=0;i<rank;i++){
      const pip = document.createElement('button');
      pip.type = 'button';
      pip.className = 'void-pip' + (i<current ? ' filled' : '');
      pip.title = (i<current) ? 'Filled — click to spend this Void Point' : 'Blank — click (or right-click) to get this Void Point back';
      wrap.appendChild(pip);
    }
    // PART H PHASE 2 - a pip click/right-click calls this function directly, bypassing
    // recalcAll() entirely, so the Quick Access panel's Void row would otherwise go stale
    // the instant a point is spent or restored while the panel is open.
    if(typeof renderQuickAccessPanel === 'function') renderQuickAccessPanel();
  }
  document.getElementById('voidPips').addEventListener('click', e=>{
    const pip = e.target.closest('.void-pip');
    if(!pip) return;
    const hidden = document.getElementById('void_current');
    let current = parseInt(hidden.value||'0',10);
    current += pip.classList.contains('filled') ? -1 : 1;
    hidden.value = current;
    renderVoidPips();
  });
  document.getElementById('voidPips').addEventListener('contextmenu', e=>{
    const pip = e.target.closest('.void-pip');
    if(!pip) return;
    e.preventDefault();
    if(pip.classList.contains('filled')) return; // right-click only restores a blank pip
    const hidden = document.getElementById('void_current');
    hidden.value = parseInt(hidden.value||'0',10) + 1;
    renderVoidPips();
  });
  document.getElementById('voidInfoBtn').addEventListener('click', ()=>{
    document.getElementById('voidInfoModalOverlay').style.display = 'flex';
  });
  document.getElementById('voidInfoClose').addEventListener('click', ()=>{
    document.getElementById('voidInfoModalOverlay').style.display = 'none';
  });
  document.getElementById('voidInfoModalOverlay').addEventListener('click', (e)=>{
    if(e.target.id==='voidInfoModalOverlay') document.getElementById('voidInfoModalOverlay').style.display = 'none';
  });

  // ---------- Spell Slots pip tracker ----------
  // spell_used_<key> (hidden input, kept for save/load compatibility) holds how many of that
  // element's slots are currently used. Total pip count is always read fresh from ring_<key>
  // (== the element's Ring Rank; for 'void' that's the existing #ring_void input) and never
  // stored separately, so raising/lowering a Ring Rank can never leave pips out of sync — a
  // Ring Rank drop just clamps "used" down to fit the new, smaller pip count.
  function renderSpellPips(key){
    const rank = Math.max(0, Math.min(10, parseInt(document.getElementById('ring_'+key).value||'0',10)));
    const hidden = document.getElementById('spell_used_'+key);
    const used = Math.max(0, Math.min(rank, parseInt(hidden.value||'0',10)));
    hidden.value = used;
    const wrap = document.getElementById('spellPips_'+key);
    wrap.innerHTML = '';
    for(let i=0;i<rank;i++){
      const pip = document.createElement('button');
      pip.type = 'button';
      pip.className = 'spell-pip spell-pip-'+key + (i<used ? ' filled' : '');
      pip.title = (i<used) ? 'Used — click to restore this spell slot' : 'Available — click to mark it used';
      wrap.appendChild(pip);
    }
    // PART H PHASE 2 - castSpell() calls this directly (see below), bypassing recalcAll()
    // entirely, so the Quick Access panel's Spell Slots row would otherwise go stale the
    // instant a spell is cast while the panel is open.
    if(typeof renderQuickAccessPanel === 'function') renderQuickAccessPanel();
  }
  function renderAllSpellSlots(){
    SPELL_ELEMENTS.forEach(el=>renderSpellPips(el.key));
    renderSpellBonusPips();
  }
  // Bonus slots: a single SHARED pool sized to the Void Ring Rank (spec: "Bonus slots = Void
  // Ring Rank... form one shared pool, not per-element — consumed for any element, but total
  // usage cannot exceed Void Rank"). One counter (#spell_bonus_used_shared) backs every
  // element's bonus-pip strip, so this renders ALL of them together from that single value —
  // using a bonus slot from any one element's row fills the same pip position on every other
  // row too, and once `used` reaches the Void Rank, no element has a bonus slot left.
  // key is optional: pass an element key to re-render just that row (e.g. after that element
  // spends a bonus slot in castSpell()); omit it to re-render every row (e.g. on Void Rank
  // change, load, or reset). Either way, the shared counter (#spell_bonus_used_shared) is only
  // ever read here to clamp/report availability — it is NEVER the fill count. Fill count for
  // a row always comes from that element's own #spell_bonus_used_visual_<key>, so using a
  // bonus slot on Earth no longer fills Fire's row too.
  function renderSpellBonusPips(key){
    const rank = Math.max(0, Math.min(10, parseInt(document.getElementById('ring_void').value||'0',10)));
    const sharedHidden = document.getElementById('spell_bonus_used_shared');
    const sharedUsed = Math.max(0, Math.min(rank, parseInt(sharedHidden.value||'0',10)));
    sharedHidden.value = sharedUsed;

    const keys = key ? [key] : SPELL_ELEMENTS.map(el=>el.key);
    keys.forEach(k=>{
      const visualHidden = document.getElementById('spell_bonus_used_visual_'+k);
      if(!visualHidden) return;
      // Clamp each element's visual fill to the shared total actually used — a row can never
      // show more pips filled than the shared pool says have been spent overall (covers stale
      // saves/manual edits), and never more than the strip's own rank-sized length.
      const visualUsed = Math.max(0, Math.min(rank, sharedUsed, parseInt(visualHidden.value||'0',10)));
      visualHidden.value = visualUsed;
      const wrap = document.getElementById('spellBonusPips_'+k);
      if(!wrap) return;
      wrap.innerHTML = '';
      for(let i=0;i<rank;i++){
        const pip = document.createElement('button');
        pip.type = 'button';
        pip.className = 'spell-bonus-pip spell-bonus-pip-'+k + (i<visualUsed ? ' filled' : '');
        pip.title = (i<visualUsed) ? 'Used — click to restore this bonus slot (shared pool across all Elements)' : 'Available — click to mark it used (shared bonus pool, usable for any Element)';
        wrap.appendChild(pip);
      }
    });
    // PART H PHASE 2 - a bonus pip click (080-identity-build-ui.js) calls this directly,
    // bypassing recalcAll() entirely, so the Quick Access panel's Bonus line would otherwise go
    // stale the instant a bonus slot is spent or restored while the panel is open.
    if(typeof renderQuickAccessPanel === 'function') renderQuickAccessPanel();
  }

  // ---------- Spell-use logic (Cast button on a Techniques/Kata/Spells entry) ----------
  // Element pips fill first; once an element is out, the caster is offered a bonus slot
  // (that element's own Void-Ring-sized bonus strip, see renderSpellBonusPips) before finally
  // being told every slot is spent. appConfirm()/appAlert() are the sheet's existing
  // sandboxed-iframe-safe modal helpers (used elsewhere for Delete/Clear confirmations),
  // reused here for the two pop-ups the spec calls for.
  async function castSpell(elementKey, spellName, mastery, keywords){
    const elMeta = SPELL_ELEMENTS.find(e=>e.key===elementKey);
    const elLabel = elMeta ? elMeta.name : elementKey;

    const elMax = Math.max(0, Math.min(10, parseInt(document.getElementById('ring_'+elementKey).value||'0',10)));
    const elUsedInput = document.getElementById('spell_used_'+elementKey);
    const elUsed = Math.max(0, Math.min(elMax, parseInt(elUsedInput.value||'0',10)));

    if(elUsed < elMax){
      elUsedInput.value = elUsed + 1;
      renderSpellPips(elementKey);
      performSpellCastRoll(elementKey, elLabel, spellName, mastery, keywords);
      return;
    }

    const bonusMax = Math.max(0, Math.min(10, parseInt(document.getElementById('ring_void').value||'0',10)));
    const bonusUsedInput = document.getElementById('spell_bonus_used_shared');
    const bonusUsed = Math.max(0, Math.min(bonusMax, parseInt(bonusUsedInput.value||'0',10)));

    if(bonusUsed < bonusMax){
      const useBonus = await appConfirm(`No ${elLabel} spell slots remain. Use bonus slot? (shared pool — ${bonusMax-bonusUsed} of ${bonusMax} remaining across all Elements)`, 'Yes', 'ghost', 'No');
      if(useBonus){
        // Shared pool (gates availability for every element) and this element's own visual
        // fill count (which pip strip shows the used slot) both advance together.
        bonusUsedInput.value = bonusUsed + 1;
        const visualInput = document.getElementById('spell_bonus_used_visual_'+elementKey);
        visualInput.value = Math.max(0, parseInt(visualInput.value||'0',10)) + 1;
        renderSpellBonusPips(elementKey);
        performSpellCastRoll(elementKey, elLabel, spellName, mastery, keywords);
      }
      return;
    }

    await appAlert(`All ${elLabel} and all bonus spell slots used.`);
  }
  // Casting Roll: rollDice = Ring + effective Shugenja School Rank for this spell (element-
  // based Affinity/Deficiency, then any keyword-based Affinity/Deficiency layered on top —
  // see effectiveSchoolRankForSpell), keepDice = Ring alone. TN = 5 + (5 × Mastery Level) —
  // e.g. Mastery 2 → TN 15. Goes through the same rollDicePool()/showRollResult() pipeline as
  // every other roll on the sheet (10-dice cap, exploding 10s, manual click-to-keep dice
  // selection), with a tnConfig so the modal shows a live pass/fail readout against this
  // spell's TN as the player adjusts which dice they keep. The pip was already consumed by
  // the caller before this runs, and nothing here can undo that — a failed roll still spent
  // the slot, and a roll's outcome never changes which slot (element or bonus) was used.
  function performSpellCastRoll(elementKey, elLabel, spellName, mastery, keywords){
    const ring = Math.max(0, Math.min(10, parseInt(document.getElementById('ring_'+elementKey).value||'0',10)));
    const schoolRank = effectiveSchoolRankForSpell(elLabel, keywords);
    // PART G PHASE 4 - the School Rank BEFORE Affinity/Deficiency moved it. Read from the same
    // field effectiveSchoolRankForElement() starts from, so the breakdown can say "base 3, +1
    // Water Affinity" instead of presenting 4 as if it were printed on the sheet.
    const schoolRankBase = parseInt(document.getElementById('f_rank').value||'0',10) || 0;
    const masteryLevel = Math.max(0, Math.round(parseFloat(mastery)||0));
    const tn = 5 + (5 * masteryLevel);
    // PART C FEATURE 3 - routed through P2 so wound penalties reach Spell Casting Rolls. The
    // TN config is passed through untouched, so the pass/fail readout still works -- and now
    // correctly reflects a wounded caster's reduced total.
    rollWithModifiers(
      `${spellName} — Casting Roll (${elLabel})`,
      makeRollContext(ROLL_KINDS.SPELL, { spellName, element:elLabel, mastery,
        // PART G PHASE 4 - the two numbers that made this pool, plus what the second one was
        // before the School's Affinity/Deficiency adjusted it.
        ringValue:ring, schoolRank, schoolRankBase }),
      ring + schoolRank, ring,
      { tnConfig:{ tn, successText:'Spell cast successfully.', failText:'Spell failed to cast.' } }
    );
  }

  // Universal spells (Commune/Sense/Summon) aren't tied to one Element — casting one asks the
  // player which Element's spell slot (and Casting Roll) to use FIRST, via the same
  // self-contained Promise-modal pattern as pickAffinityElement() above (resolves with the
  // chosen Element string on Confirm, or null if the X button/empty selection cancels). Void
  // is excluded: all three Universal spells work on Air/Earth/Fire/Water spirits/matter only
  // (see their descriptions in SPELL_LIBRARY). Once an Element is confirmed, casting proceeds
  // through the exact same castSpell() flow as any other spell of that Element — element pip
  // first, then bonus-slot pop-up, then "all slots used" — nothing about that logic changes.
  // Cancelling the picker closes with no fill and no roll, same as declining the bonus-slot
  // pop-up inside castSpell().
  const UNIVERSAL_SPELL_ELEMENTS = ['Air','Earth','Fire','Water'];
  // Why (if at all) a given Element can't be picked for THIS Universal spell: effective School
  // Rank for that Element (same effectiveSchoolRankForSpell() the actual roll uses — Affinity/
  // Deficiency and Chuda's/Yogo's keyword modifiers all included) has to at least meet the
  // spell's own Mastery Level, exactly like spellEligibility() requires for learning a spell
  // in the first place. Returns null when the Element is fine to pick, or an explanatory
  // string when it isn't — worded around a Deficiency specifically (fixed, like Kuni's Air, or
  // player-chosen, like Chuda's) when that's what caused it, since that's the far more common
  // and more informative case; a generic "rank too low" message covers every other cause.
  function universalSpellElementBlockReason(element, mastery, keywords, ignoreRankLimit){
    if(ignoreRankLimit) return null; // Maho: "no limitation on School Rank or Insight Rank to cast" — every Element is pickable.
    const effRank = effectiveSchoolRankForSpell(element, keywords);
    if(effRank >= mastery) return null;
    const { deficiency } = getActiveSchoolElementalProfile();
    const { deficiencyElement, deficiencyExcludesKeyword } = getActiveSchoolKeywordProfile();
    const spellKeywords = keywords || [];
    const isFixedDeficiency = deficiency && deficiency === element;
    const isChosenDeficiency = deficiencyElement && deficiencyElement === element
      && !(deficiencyExcludesKeyword && spellKeywords.includes(deficiencyExcludesKeyword));
    if(isFixedDeficiency || isChosenDeficiency){
      return `You can't use ${element} to cast this spell — your School has a Deficiency in ${element}, dropping your effective School Rank to ${effRank} (this spell needs a school rank of at least ${mastery}).`;
    }
    return `Your effective School Rank in ${element} (${effRank}) is too low to cast this Mastery ${mastery} spell.`;
  }
  function pickUniversalSpellElement(spellName, mastery, keywords, ignoreRankLimit){
    return new Promise(resolve=>{
      const overlay = document.getElementById('universalSpellPickModalOverlay');
      const grid = document.getElementById('universalSpellPickGrid');
      document.getElementById('universalSpellPickSubtitle').textContent = `${spellName} — select one Element`;
      const blockReasons = UNIVERSAL_SPELL_ELEMENTS.map(el=>universalSpellElementBlockReason(el, mastery, keywords, ignoreRankLimit));
      grid.innerHTML = UNIVERSAL_SPELL_ELEMENTS.map((el,i)=>{
        const reason = blockReasons[i];
        return `
        <div class="affinity-pick-item${reason?' disabled':''}" data-el="${escAttr(el)}"${reason?` title="${escAttr(reason)}"`:''}>
          <label for="universalSpellPick_${escAttr(el)}">${escHtml(el)}</label>
          <input type="checkbox" id="universalSpellPick_${escAttr(el)}">
        </div>`;
      }).join('');
      overlay.style.display = 'flex';
      const items = Array.from(grid.querySelectorAll('.affinity-pick-item'));
      const boxes = items.map(item=>item.querySelector('input[type="checkbox"]'));
      // A blocked Element (see blockReasons above) never toggles: caught here in the capture
      // phase — before the browser's default check-toggle behavior runs for either the
      // checkbox itself or its <label> — cancelled, and explained via an appAlert() pop-up.
      // Deliberately NOT using the native `disabled` attribute for this: a disabled input
      // can't be clicked at all in most browsers, so it could never show the player WHY.
      items.forEach((item,i)=>{
        const reason = blockReasons[i];
        if(!reason) return;
        item.addEventListener('click', (ev)=>{
          ev.preventDefault();
          ev.stopPropagation();
          appAlert(reason);
        }, true);
      });
      // Ticking one box unticks every other — only one Element can be selected at a time.
      // (Blocked boxes are skipped — see items.forEach above — so they never receive a
      // `change` event to begin with.)
      boxes.forEach((box,i)=>{
        if(blockReasons[i]) return;
        box.addEventListener('change', ()=>{
          if(box.checked){
            boxes.forEach((other,j)=>{ if(j!==i){ other.checked = false; items[j].classList.remove('checked'); } });
            items[i].classList.add('checked');
          } else {
            items[i].classList.remove('checked');
          }
        });
      });
      const confirmBtn = document.getElementById('universalSpellPickConfirm');
      const xBtn = document.getElementById('universalSpellPickX');
      const cleanup = (result)=>{
        overlay.style.display = 'none';
        confirmBtn.removeEventListener('click', onConfirm);
        xBtn.removeEventListener('click', onCancel);
        resolve(result);
      };
      const onConfirm = ()=>{
        const chosen = items.find(item=>item.querySelector('input[type="checkbox"]').checked);
        if(!chosen){ setStatus('Select an Element before confirming.'); return; }
        cleanup(chosen.dataset.el);
      };
      const onCancel = ()=>cleanup(null);
      confirmBtn.addEventListener('click', onConfirm);
      xBtn.addEventListener('click', onCancel);
    });
  }
  async function castUniversalSpell(spellName, mastery, keywords){
    const chosen = await pickUniversalSpellElement(spellName, mastery, keywords);
    if(!chosen) return; // cancelled — no fill, no roll
    castSpell(chosen.toLowerCase(), spellName, mastery, keywords);
  }

  // ---------- Maho spell casting (separate pipeline from castSpell/castUniversalSpell) ----------
  // Maho spells (spellIsMaho, see makeEntry/buildTechQuickAdd) are deliberately NOT routed
  // through the normal castSpell()/performSpellCastRoll() pipeline, because they break several
  // of its rules at once:
  //   - No spell slot (element or bonus) is ever consumed — Maho sits entirely outside the
  //     Spell Slot economy, regardless of the spell's Element.
  //   - There's no Mastery-vs-effective-Rank limitation on casting it (already true of adding
  //     it to Techniques in the first place — see techQuickAddOptionsHTML/buildTechQuickAdd —
  //     but restated here since this is also the enforcement point for a Universal Maho spell's
  //     Element choice, via pickUniversalSpellElement's ignoreRankLimit=true).
  //   - The Casting Roll's dice pool swaps School Rank for Insight Rank for a non-Shugenja
  //     caster (a Shugenja caster — or an unset/no-School sheet — still uses effective School
  //     Rank exactly like any other spell; only a confirmed Bushi lock changes this).
  //   - A blood-source pop-up runs before the roll; ✕/outside-click aborts the entire cast (no
  //     Wounds, no Taint, no roll) — only choosing "Own Blood" or "Someone Else's Blood" lets
  //     casting proceed, and only "Own Blood" applies Wounds immediately, unconditionally
  //     (before the roll, so it happens whether or not the roll goes on to succeed or fail).
  //   - A successful cast (read off the roll modal's own pass/fail readout once the player
  //     closes it — see currentRollOnClose/closeRollModal) gains Taint equal to one less than
  //     the spell's Mastery Rank, minimum 1 — a failed cast gains none.
  async function castMahoSpell(elementKey, spellName, mastery, keywords){
    let finalElementKey = elementKey;
    let elLabel;
    if(elementKey === 'universal'){
      // Maho: no Rank/Mastery limitation on which Element can be chosen (ignoreRankLimit=true).
      const chosen = await pickUniversalSpellElement(spellName, mastery, keywords, true);
      if(!chosen) return; // cancelled — no blood asked, no wounds, no roll
      finalElementKey = chosen.toLowerCase();
      elLabel = chosen;
    } else {
      const elMeta = SPELL_ELEMENTS.find(e=>e.key===elementKey);
      elLabel = elMeta ? elMeta.name : elementKey;
    }

    const masteryLevel = Math.max(0, Math.round(parseFloat(mastery)||0));

    // Blood-source pop-up — asked every time, before anything else happens. "Own Blood" (OK)
    // resolves 'ok'; "Someone Else's Blood" (Cancel-labelled button) resolves 'cancel' — both
    // proceed with the cast. Closing via ✕ (or clicking outside) resolves null and aborts the
    // cast entirely: no Wounds, no Taint, no roll, same as if Cast was never clicked.
    const bloodChoice = await appConfirm3Way(
      `Casting ${spellName} calls for blood to fuel the ritual. Use your own blood, or someone else's?`,
      'Own Blood', 'ghost', "Someone Else's Blood"
    );
    if(bloodChoice === null){
      setStatus(`${spellName}: casting cancelled.`);
      return;
    }
    const useOwnBlood = bloodChoice === 'ok';

    // Own blood: the caster suffers Wounds equal to twice the spell's Mastery Rank (Mastery 1
    // = 2 Wounds), applied right now and unconditionally — this happens whether or not the
    // Casting Roll below goes on to succeed.
    if(useOwnBlood){
      const woundCost = masteryLevel * 2;
      const woundsInput = document.getElementById('f_woundsTaken');
      const currentWounds = parseInt(woundsInput.value||'0',10) || 0;
      woundsInput.value = currentWounds + woundCost;
      renderWounds();
      setStatus(`${spellName}: cast using your own blood — took ${woundCost} Wounds.`);
    } else {
      setStatus(`${spellName}: cast using someone else's blood.`);
    }

    // Casting Roll: a Shugenja (or a sheet with no School locked in yet) rolls Ring + effective
    // School Rank exactly like any other spell. A confirmed non-Shugenja (Bushi) instead rolls
    // Ring + Insight Rank, since they have no School Rank of their own to draw on for a ritual
    // outside their training. No spell slot is touched either way.
    const ring = Math.max(0, Math.min(10, parseInt(document.getElementById('ring_'+finalElementKey).value||'0',10)));
    const casterLock = characterCasterLock();
    const rankBonus = casterLock === 'bushi'
      ? (parseInt(document.getElementById('f_insightRank').value||'0',10) || 0)
      : effectiveSchoolRankForSpell(elLabel, keywords);
    const tn = 5 + (5 * masteryLevel);

    // PART C FEATURE 3 - routed through P2 so wound penalties reach Maho Casting Rolls. The
    // TN config and its onClose Taint hook ride along inside tnConfig, unchanged.
    rollWithModifiers(
      `${spellName} — Maho Casting Roll (${elLabel})`,
      makeRollContext(ROLL_KINDS.SPELL, { spellName, element:elLabel, maho:true,
        // PART G PHASE 4 - a bushi maho-tsukai rolls Insight Rank where a shugenja rolls School
        // Rank, so the label travels with the number rather than being assumed downstream.
        ringValue:ring, schoolRank:rankBonus,
        schoolRankLabel: casterLock === 'bushi' ? 'Insight Rank' : 'School Rank' }),
      ring + rankBonus, ring,
      { tnConfig: {
        tn,
        successText: 'Spell cast successfully.',
        failText: 'Spell failed to cast.',
        // Taint is gained only if the roll ultimately reads as a success once the player is
        // done adjusting kept dice and closes the modal — see closeRollModal.
        onClose: (success)=>{
          if(success===true){
            const taintGain = Math.max(1, masteryLevel - 1);
            const taintInput = document.getElementById('f_taint');
            const currentTaint = parseInt(taintInput.value||'0',10) || 0;
            taintInput.value = currentTaint + taintGain;
            setStatus(`${spellName}: cast successfully — gained ${taintGain} Taint.`);
          }
        }
      } }
    );
  }

  // Spell Memorisation — clicking the tick box. Ticking ON spends XP equal to the spell's
  // Mastery Rank through the exact same total-XP pipeline as Skills/Emphases/Kata: recalcAll()
  // reads memorisationXpCost back off the entry (see the techXP loop) rather than this handler
  // maintaining any separate ledger. Ticking OFF is gated behind a confirmation (the native
  // click already toggled the box to unchecked by the time this handler runs, so it's put back
  // to checked immediately and only actually un-memorised if the player confirms) — declining
  // simply leaves it checked/memorised, unchanged. "Refunding" XP is just clearing
  // memorisationXpCost off the entry, the same derived-total pipeline then naturally excludes
  // it on the next recalcAll(), with no separate refund bookkeeping needed. isMemorised/
  // memorisationXpCost persist through collectData/applyData like every other dataset-* field
  // already on a spell entry. See makeEquipRow's scroll-removal handler for the matching
  // "memorisation overrides scroll dependency" exemption — un-memorising deliberately doesn't
  // touch that logic at all; it already reads dataset.isMemorised fresh every time a scroll
  // might be removed, so un-memorising here correctly reinstates that dependency on its own.
  document.getElementById('techList').addEventListener('click', e=>{
    const memoCheckbox = e.target.closest('.spell-memo-checkbox');
    if(memoCheckbox){
      const entry = memoCheckbox.closest('.entry');
      const mastery = parseInt(entry.dataset.spellMastery||'0',10);
      const spellName = (entry.querySelector('.en-name').value||'').trim() || 'Spell';
      if(memoCheckbox.checked){
        entry.dataset.isMemorised = 'true';
        entry.dataset.memorisationXpCost = mastery;
        memoCheckbox.title = 'Memorised — remains castable and ignores Spell Scroll requirements even while checked; untick to un-memorise and refund the XP';
        memoCheckbox.parentElement.title = memoCheckbox.title;
        setStatus(`Memorised ${spellName} (${mastery} XP).`);
        recalcAll();
        return;
      }
      // Native click already unchecked the box — hold it checked until the player decides.
      memoCheckbox.checked = true;
      appConfirm(
        'Un-memorising this spell means that if its scroll is removed from your equipment, the spell will also be removed. Continue?',
        'Confirm', 'ghost', 'Cancel'
      ).then(ok=>{
        if(!ok) return; // Cancel: stays checked/memorised, nothing else changes.
        entry.dataset.isMemorised = 'false';
        delete entry.dataset.memorisationXpCost;
        memoCheckbox.checked = false;
        memoCheckbox.title = `Memorise this spell — spends ${mastery} XP (its Mastery Rank) while checked`;
        memoCheckbox.parentElement.title = memoCheckbox.title;
        setStatus(`Un-memorised ${spellName} — ${mastery} XP refunded.`);
        recalcAll();
      });
      return;
    }
    const btn = e.target.closest('.spell-cast-btn');
    if(!btn) return;
    const entry = btn.closest('.entry');
    const elementKey = entry.dataset.spellElement;
    if(!elementKey) return;
    const spellName = entry.querySelector('.en-name').value.trim() || 'Spell';
    const mastery = parseInt(entry.dataset.spellMastery||'0',10);
    const keywords = entry.dataset.spellKeywords ? entry.dataset.spellKeywords.split(',') : [];
    if(entry.dataset.spellIsMaho === 'true'){
      castMahoSpell(elementKey, spellName, mastery, keywords);
    } else if(elementKey === 'universal'){
      castUniversalSpell(spellName, mastery, keywords);
    } else {
      castSpell(elementKey, spellName, mastery, keywords);
    }
  });

  // The Spell Slots card only makes sense for a Shugenja — characterCasterLock() reads the
  // character's applied School(s) and returns 'shugenja', 'bushi', or null (no School locked
  // in yet, i.e. a fresh/partway-built sheet). The card is shown for 'shugenja', hidden for
  // both other cases, and re-checked every recalcAll() so it reacts immediately to Apply
  // School / Remove School rather than needing a page reload.
  // The "+ Add Spell Scroll" button on the Equipment table, unlike the Spell Slots card, is
  // NOT restricted to Shugenja — any School can end up owning a scroll (most obviously a Maho
  // Scroll, which any character can pick up and stash in Equipment even without Shugenja
  // training), so it stays visible regardless of characterCasterLock(). It's a static
  // print-hide button with no dynamic display toggling needed (see its <button> tag), so there
  // is nothing else to do here for it.
  function updateSpellSlotsVisibility(){
    const isShugenja = characterCasterLock() === 'shugenja';
    document.getElementById('spellSlotsSection').style.display = isShugenja ? '' : 'none';
    // BUGFIX (Spell Slots tab visibility): the carousel's own watchVisibility() picks this
    // change up asynchronously via a MutationObserver on this element's style attribute --
    // correct, and left running for any other conditional page. But this line is the one
    // place in the whole sheet that KNOWS the moment visibility changed; calling the
    // carousel's synchronous refreshVisibility() right here removes any dependency on the
    // observer's callback having already landed before the next thing the caller does (e.g.
    // Apply School's own handler continuing on to touch other UI). Guarded because this file
    // has no other reason to assume the carousel controller exists.
    if(window.__L5R_CAROUSEL__ && typeof window.__L5R_CAROUSEL__.refreshVisibility === 'function'){
      window.__L5R_CAROUSEL__.refreshVisibility();
    }
  }

  function recalcAll(){
    renderVoidPips();
    // Keeps the Clan/Family/School card's Affinity/Deficiency display (added just below the
    // pre-apply preview) in sync with whichever School is actually applied — cheap to
    // recompute and correct after Apply School, after loading a saved character, or after any
    // other change that runs through recalcAll().
    // NOTE: only the School-Rank-INDEPENDENT displays run here. Anything that reads f_rank is
    // deferred until after the School Rank block below has written it — see the note there.
    renderAppliedSchoolAffinity();
    renderMonkFieldNotes();
    // Rings are always "the lower of their two Traits" — recompute every Ring here (not just
    // via the Trait <input> "input" listener below) so it stays correct no matter how a Trait
    // changed: typing, Apply Family/Apply School (which set .value in JS and don't fire a DOM
    // "input" event), or a JSON import.
    RINGS.forEach(r=>{
      const vals = r.traits.map(tt=>parseInt(document.getElementById('trait_'+tt.key).value||'0',10));
      document.getElementById('ring_'+r.key).value = Math.min(...vals);
    });
    // Spell Slots' max pips are derived from Ring Rank, so re-render only after every Ring
    // (including the four derived ones just above) is up to date.
    renderAllSpellSlots();
    updateSpellSlotsVisibility();
    // PART B: a weapon row's Attack/Damage notation is derived from Traits and Skill Ranks,
    // so it has to be recomputed here for the same reason the Rings above are — raising
    // Strength, buying a Skill Rank, applying a School, or loading a save all change these
    // numbers without firing an event on the weapon row itself. Only derived, non-manual
    // values are written (see refreshWeaponRow), so this never overwrites player input.
    refreshAllWeaponRows();
    // Insight
    const ringVals = RINGS.map(r=>parseInt(document.getElementById('ring_'+r.key).value||'0',10));
    const voidVal = parseInt(document.getElementById('ring_void').value||'0',10);
    const ringSum = ringVals.reduce((a,b)=>a+b,0) + voidVal;
    let skillRankSum = 0, skillXP = 0;
    document.querySelectorAll('#skillsBody tr').forEach(tr=>{
      const rankEl = tr.querySelector('.sk-rank');
      const rank = parseInt(rankEl.value||'0',10);
      const emphCount = getPaidEmphCount(tr);
      const isSchool = tr.querySelector('.sk-school').checked;
      // A manually-ticked School Skill with no explicit floor set defaults to the standard
      // "first Rank free" rule (floor 1). A skill Apply School itself granted at a specific
      // Rank (e.g. Kuni Shugenja's Lore: Shadowlands 2) has data-free set to that Rank instead
      // — see the Apply School skill-processing loop and makeSkillRow — so its whole granted
      // Rank is free, and only XP spent going above it (e.g. Rank 2 -> 3) costs normally.
      const freeFloor = isSchool ? Math.max(1, parseInt(rankEl.dataset.free||'0',10)) : 0;
      skillRankSum += rank;
      const cost = skillCost(rank, emphCount, freeFloor);
      skillXP += cost;
      tr.querySelector('.sk-cost').textContent = cost+' xp';
      renderSkillMasteryNote(tr);
      refreshEmphWidgetsForSkill(tr);
    });
    const insightBonus = parseFloat(document.getElementById('f_insightBonus').value||'0');
    const insightPts = ringSum*10 + skillRankSum + insightBonus;
    document.getElementById('f_insightPts').value = insightPts;
    document.getElementById('f_insightRank').value = insightRankFromPoints(insightPts);

    // ---------- Multiple Schools: active-School Rank tracking + Technique unlocking ----------
    // The LAST entry in the Schools list (see getSchoolsList) is always the active School.
    // Earlier entries are frozen the moment a new School is added (Rule 3A) and are left
    // untouched here. f_school/f_rank are kept in sync with the active entry so every other
    // part of the sheet that already reads them (Kata eligibility, Base Roll, hints, etc.)
    // keeps working unchanged.
    const schoolsList = getSchoolsList();
    document.getElementById('f_insightToNextRank').value = calculateSchoolRank(insightPts).insightToNextRank;
    if(schoolsList.length){
      const activeIdx = schoolsList.length-1;
      const active = schoolsList[activeIdx];
      const isOriginalSchool = activeIdx===0; // the character's starting School, not one added via Multiple Schools
      // Rule 3: combined School Rank across every School can never exceed Insight Rank — this
      // clamps the active School down (even below its own floor) if Insight Rank has dropped.
      const currentSchoolRank = computeCappedActiveRank(schoolsList, insightPts);
      if(!active.frozen) active.floorRank = currentSchoolRank; // never-decreasing floor, itself cap-respecting
      saveSchoolsList(schoolsList);

      document.getElementById('f_school').value = active.name;
      document.getElementById('f_rank').value = currentSchoolRank;

      // Rule 4: a School added via Multiple Schools only unlocks Techniques once the
      // character has at least 1 Rank in ALL of that School's own concrete School Skills.
      // The character's original School is unaffected by this gate (chargen already covers it).
      const gateOk = isOriginalSchool || hasSchoolSkillOverlap(active.name);
      if(gateOk){
        const unlockOutcome = applyUnlockedTechniquesToList(active.name, currentSchoolRank);
        if(unlockOutcome.added.length){
          setStatus(`${active.name} — School Rank ${currentSchoolRank}: unlocked ${unlockOutcome.added.join(', ')}.`);
        }
      }
    } else {
      document.getElementById('f_rank').value = 1;
    }
    refreshMultipleSchoolsUI();

    // Everything that reads the School Rank has to run AFTER f_rank is written just above,
    // not at the top of recalcAll(). Running these early made them a full recalc stale: the
    // Kiho dropdown priced and gated against the PREVIOUS Rank, the free-pick counter showed
    // the previous Rank's allowance, and the Alternate Path picker offered the Paths for the
    // Rank before the one the character had just reached. The symptom was a clean one-Rank
    // lag, which is easy to miss because everything still looked internally consistent.
    refreshTechQuickAddOptions();
    renderPathPicker();
    renderKihoGrantNote();

    // Trait + Void XP — only ranks bought above each trait's free floor (base 2, raised by
    // Family/School bonuses) cost XP.
    let traitXP = 0;
    RINGS.forEach(r=>r.traits.forEach(t=>{
      const el = document.getElementById('trait_'+t.key);
      traitXP += traitCost(parseInt(el.value||'2',10), parseInt(el.dataset.free||'2',10));
    }));
    const voidFreeFloor = parseInt(document.getElementById('ring_void').dataset.free||'2',10);
    const voidXP = voidCost(voidVal, voidFreeFloor);

    // Advantages / Disadvantages
    let advXP = 0, disadvXP = 0;
    document.querySelectorAll('#advList .entry').forEach(div=>{
      advXP += parseFloat(div.querySelector('.en-cost').value||'0');
    });
    document.querySelectorAll('#disadvList .entry').forEach(div=>{
      disadvXP += parseFloat(div.querySelector('.en-cost').value||'0');
    });

    // Techniques / Kata / Spells — a Kata costs XP equal to its Mastery Level (auto-filled when
    // added from the dropdown); freeform entries and Spells default to 0 but stay editable.
    // A memorised Spell adds its memorisationXpCost (Mastery Rank, spent once when the
    // "Memorised" tick box was checked — see the #techList click handler) on top of that,
    // the same way every other XP source here is just summed into the total.
    let techXP = 0;
    document.querySelectorAll('#techList .entry').forEach(div=>{
      const costEl = div.querySelector('.en-cost');
      if(costEl) techXP += parseFloat(costEl.value||'0');
      techXP += parseFloat(div.dataset.memorisationXpCost||'0');
    });

    const adjustment = parseFloat(document.getElementById('f_xpAdjust').value||'0');
    const spent = traitXP + voidXP + skillXP + advXP - disadvXP + techXP + adjustment;
    document.getElementById('f_xpSpent').value = spent;
    const total = parseFloat(document.getElementById('f_xpTotal').value||'0');
    document.getElementById('f_xpRemain').value = (total-spent);

    document.getElementById('xpBreakdown').innerHTML = `
      <div>Traits: <strong>${traitXP}</strong></div>
      <div>Void: <strong>${voidXP}</strong></div>
      <div>Skills+Emph: <strong>${skillXP}</strong></div>
      <div>Kata/Tech: <strong>${techXP}</strong></div>
      <div>Advantages: <strong>+${advXP}</strong></div>
      <div>Disadvantages: <strong>−${disadvXP}</strong></div>
    `;

    // Combat TN: base TN to be Hit = (Reflexes x5) + 5, plus armor bonus
    const reflexes = parseInt(document.getElementById('trait_reflexes').value||'2',10);
    const baseTN = reflexes*5 + 5;
    document.getElementById('f_baseTN').value = baseTN;
    const armorTN = parseFloat(document.getElementById('f_armorTN').value||'0');
    // PART C FEATURE 2 - Armor TN is character state, not a roll, so the Stance effects that
    // change it (Full Attack -10, Defense +Air+Defense Rank, Full Defense's half-roll) land here
    // rather than in the P2 pipeline.
    const stanceTN = (typeof getStanceArmorTNBonus === 'function') ? getStanceArmorTNBonus() : 0;
    // PART C FEATURE 4 - a spent Void Point raises Armor TN until end of round, stacking
    // additively with armour and with every stance effect.
    const voidTN = (typeof getVoidArmorTNBonus === 'function') ? getVoidArmorTNBonus() : 0;
    // PART C FEATURE 7 - RAW: "characters wielding two weapons add their Insight Rank to their
    // Armor TN". Additive with armour, stance and Void exactly as those are with each other,
    // and 0 for anyone not actually holding two weapons.
    const dualTN = (typeof getDualWieldArmorTNBonus === 'function') ? getDualWieldArmorTNBonus() : 0;
    // PART C FEATURE 8 - Way of the Dragon adds School Rank on top, explicitly "cumulative with
    // the normal bonus for wielding two weapons". 0 for anyone who is not a dual-wielding
    // Mirumoto, so this term is invisible to every other character.
    const mirumotoTN = (typeof getMirumotoArmorTNBonus === 'function') ? getMirumotoArmorTNBonus() : 0;
    document.getElementById('f_currentTN').value =
      baseTN + armorTN + stanceTN + voidTN + dualTN + mirumotoTN;

    // Initiative: roll (Reflexes + Insight Rank), keep Reflexes
    const insightRank = parseInt(document.getElementById('f_insightRank').value||'0',10);
    // PART C FEATURE 2 - Center grants +10 to the Initiative Score for the round after it.
    const stanceInit = (typeof getStanceInitiativeBonus === 'function') ? getStanceInitiativeBonus() : 0;
    const voidInit = (typeof getVoidInitiativeBonus === 'function') ? getVoidInitiativeBonus() : 0;
    const totalInit = stanceInit + voidInit;      // PART C FEATURE 4 - additive with Center
    document.getElementById('f_initiative').value =
      formatRollNotation(reflexes+insightRank, reflexes) + (totalInit ? ' +' + totalInit : '');

    renderWounds();
    // PART H PHASE 9 - last, so it reads whatever Clan is applied after everything else this
    // pass computed. recalcAll() is the only path that changes #f_clan (Apply Family, in
    // 080-identity-build-ui.js, always calls it right after) and the only path a saved
    // character's Clan is restored on load, so this needs no narrower hook of its own.
    if(typeof applyClanTheme === 'function') applyClanTheme();
    // PART J PHASE 5 - the ValidationReport, last of all, so every rule reads the numbers this
    // pass has finished writing rather than the previous pass's. It is a pure read of the DOM
    // plus a render into #validationReport, so running it here costs one more pass over the
    // Skills table and changes nothing else. Guarded like the three phases above it: removing
    // 209.5-feat-character-validator.js without also editing this file leaves this a silent
    // no-op instead of a ReferenceError that would abort the rest of recalcAll().
    if(typeof renderValidationReport === 'function') renderValidationReport();
    // PART J PHASE 8 - refresh the per-spell castability badges (209.7-feat-casting-
    // diagnostics.js). Every input they depend on -- School, School Rank, Deficiency, the
    // Equipment scroll rows, slot counts -- is settled by this point in the pass, so this runs
    // last alongside the ValidationReport above. Guarded for the same reason it is.
    if(typeof refreshAllCastingDiagnosticButtons === 'function') refreshAllCastingDiagnosticButtons();
  }

  document.getElementById('f_woundsTaken').addEventListener('input', renderWounds);
  // PART H PHASE 1.6: the slider and stepper are the two new synced controls. Each writes
  // straight into f_woundsTaken's own value and calls renderWounds() directly -- the same
  // thing f_woundsTaken's own 'input' listener above does -- rather than dispatching a
  // synthetic event on it, so a single control change never renders the bar twice.
  document.getElementById('woundsTakenSlider').addEventListener('input', ()=>{
    document.getElementById('f_woundsTaken').value = document.getElementById('woundsTakenSlider').value;
    renderWounds();
  });
  document.getElementById('woundStepDown').addEventListener('click', ()=>{
    const el = document.getElementById('f_woundsTaken');
    const v = parseInt(el.value||'0',10) || 0;
    if(v > 0){ el.value = v - 1; renderWounds(); }
  });
  document.getElementById('woundStepUp').addEventListener('click', ()=>{
    const el = document.getElementById('f_woundsTaken');
    const earth = parseInt(document.getElementById('ring_earth').value||'2',10);
    const max = computeWoundThresholds(earth)[WOUND_LEVELS.length-1];
    const v = parseInt(el.value||'0',10) || 0;
    if(v < max){ el.value = v + 1; renderWounds(); }
  });
  document.getElementById('ring_void').addEventListener('input', recalcAll);
  document.getElementById('f_insightBonus').addEventListener('input', recalcAll);
  document.getElementById('f_xpTotal').addEventListener('input', recalcAll);
  document.getElementById('f_xpAdjust').addEventListener('input', recalcAll);
  document.getElementById('f_armorTN').addEventListener('input', recalcAll);
  // Typing directly into the School field (without using Apply School / Add School) renames
  // whichever School is currently active, preserving its Rank-tracking data; if the character
  // has no School yet, it creates their first one. Frozen (earlier) Schools are unaffected.
  document.getElementById('f_school').addEventListener('input', ()=>{
    const name = document.getElementById('f_school').value.trim();
    const list = getSchoolsList();
    if(list.length){ list[list.length-1].name = name; }
    else if(name){ list.push({ name, frozen:false, frozenRank:null, floorRank:1, anchorInsightRank:0 }); }
    saveSchoolsList(list);
    recalcAll();
  });

  document.getElementById('btnRollInitiative').addEventListener('click', ()=>{
    const reflexes = parseInt(document.getElementById('trait_reflexes').value||'2',10);
    const insightRank = parseInt(document.getElementById('f_insightRank').value||'0',10);
    // PART C FEATURE 2 - routed through P2 so Center's +10 reaches the total honestly.
    // PART G PHASE 4 - both halves of an Initiative Roll declared, so the breakdown can split
    // "5k3" back into Reflexes and Insight Rank.
    rollWithModifiers('Initiative',
      makeRollContext(ROLL_KINDS.INITIATIVE, { traitValue:reflexes, insightRank }),
      reflexes+insightRank, reflexes);
  });

  // header name sync
  document.getElementById('f_name').addEventListener('input', e=>{
    document.getElementById('headerName').textContent = e.target.value.trim() || 'Unnamed Character';
  });
